    let carry = cpsr & FLAG_CARRY != 0;
    let overflow = cpsr & FLAG_OVERFLOW != 0;
    match condition & 0xF {
        0x0 => zero,                          // EQ
        0x1 => !zero,                         // NE
        0x2 => carry,                         // CS/HS
