                continue;
            }
            let mut source = bus.read16(base) as u32 | (bus.read16(base + 2) as u32) << 16;
            let mut destination = bus.read16(base + 4) as u32 | (bus.read16(base + 6) as u32) << 16;
            let count = match bus.read16(base + 8) {
                0 => 0x4000,
                n => n as u32,
            };
            let word = control & 0x400 != 0;
            let step: i32 = if word { 4 } else { 2 };
            let delta = |mode: u16| match mode {
                0 | 3 => step,
                1 => -step,
                _ => 0,
            };
            let source_delta = delta((control >> 7) & 3);
            let destination_delta = delta((control >> 5) & 3);
            for _ in 0..count {
                if word {
                    let v = bus.read32(source);
                    bus.write32(destination, v);
                } else {
                    let v = bus.read16(source);
                    bus.write16(destination, v);
                }
                source = source.wrapping_add(source_delta as u32);
                destination = destination.wrapping_add(destination_delta as u32);
            }
            bus.write16(base + 10, control & 0x7FFF);
        }
    }

    #[test]
    #[ignore]
    fn replay() {
        let rom = std::fs::read(std::env::var("ROM").unwrap()).unwrap();
        let replay = std::fs::read_to_string(std::env::var("REPLAY").unwrap()).unwrap();
        let frames: u32 = std::env::var("FRAMES").unwrap().parse().unwrap();
        let mut key_changes = std::collections::HashMap::new();
        for line in replay.lines().filter(|line| !line.starts_with('#') && !line.is_empty()) {
            let mut parts = line.split_whitespace();
            let frame: u32 = parts.next().unwrap().parse().unwrap();
            key_changes.insert(frame, u32::from_str_radix(parts.next().unwrap(), 16).unwrap());
        }
        let mut gba = crate::gba::Gba::new(&rom);
        for frame in 0..frames {
            if let Some(&keys) = key_changes.get(&frame) {
                gba.set_keys(keys);
            }
            let mut remaining = crate::gba::CYCLES_PER_FRAME as i64;
            while remaining > 0 {
                let cycles = gba.cpu.step(&mut gba.bus);
                dma_hack(&mut gba.bus);
                gba.bus.ppu.step(cycles, &mut gba.bus.irq);
                remaining -= cycles as i64;
            }
        }
        let mut output = b"P6\n240 160\n255\n".to_vec();
        for &pixel in gba.bus.ppu.framebuffer.iter() {
            output.extend_from_slice(&[pixel as u8, (pixel >> 8) as u8, (pixel >> 16) as u8]);
        }
        std::fs::write(std::env::var("OUT").unwrap(), output).unwrap();
    }
}

