30	/// Execute one ARM opcode whose condition already passed (checked in `Cpu::step`). R15 reads as
31	/// the opcode's address + 8. Returns internal cycles only; bus accesses are counted by the bus.
32	pub(super) fn execute_arm(cpu: &mut Cpu, bus: &mut Bus, opcode: u32) -> u32 {
33	    match (opcode >> 25) & 0b111 {
34	        0b000 => execute_group_zero(cpu, bus, opcode),
35	        0b001 => {
36	            if is_psr_transfer(opcode) {
37	                execute_psr_transfer(cpu, opcode)
38	            } else {
39	                execute_data_processing(cpu, opcode)
40	            }
41	        }
42	        0b010 => execute_single_data_transfer(cpu, bus, opcode),
43	        0b011 if bit(opcode, 4) => undefined_instruction(cpu),
44	        0b011 => execute_single_data_transfer(cpu, bus, opcode),
45	        0b100 => execute_block_data_transfer(cpu, bus, opcode),
46	        0b101 => execute_branch(cpu, opcode),
47	        0b111 if bit(opcode, 24) => {
48	            cpu.enter_exception(Exception::SoftwareInterrupt);
49	            0
50	        }
51	        // Coprocessor opcodes: the GBA has no coprocessor, so they trap as undefined.
52	        _ => undefined_instruction(cpu),
53	    }
54	}
55	
56	/// Opcode bits 27-25 = 000: BX, multiplies, SWP, halfword transfers, PSR transfer and ALU ops
57	/// share this space (gbatek: ARM Instruction Summary).
58	fn execute_group_zero(cpu: &mut Cpu, bus: &mut Bus, opcode: u32) -> u32 {
59	    if opcode & 0x0FFF_FFF0 == 0x012F_FF10 {
60	        return execute_branch_and_exchange(cpu, opcode);
61	    }
62	    if opcode & 0xF0 == 0x90 {
63	        return match (opcode >> 23) & 0b11 {
64	            0b00 => execute_multiply(cpu, opcode),
65	            0b01 => execute_multiply_long(cpu, opcode),
66	            0b10 if (opcode >> 20) & 0b11 == 0 => execute_swap(cpu, bus, opcode),
67	            _ => undefined_instruction(cpu),
68	        };
69	    }
70	    if bit(opcode, 7) && bit(opcode, 4) {
71	        return execute_halfword_transfer(cpu, bus, opcode);
72	    }
73	    if is_psr_transfer(opcode) {
74	        return execute_psr_transfer(cpu, opcode);
75	    }
76	    execute_data_processing(cpu, opcode)
77	}
78	
79	/// TST/TEQ/CMP/CMN with S=0 encode MRS/MSR (gbatek: ARM Opcodes: PSR Transfer).
80	fn is_psr_transfer(opcode: u32) -> bool {
81	    (opcode >> 23) & 0b11 == 0b10 && !bit(opcode, 20)
82	}
83	
84	/// Take the Undefined Instruction exception (gbatek: ARM CPU Exceptions).
85	fn undefined_instruction(cpu: &mut Cpu) -> u32 {
86	    cpu.enter_exception(Exception::UndefinedInstruction);
87	    0
88	}
89	
90	// ---- Branches ----
91	
92	/// B and BL: PC-relative jump by a signed 24-bit word offset (gbatek: ARM Opcodes: Branch and
93	/// Branch with Link (B, BL, BLX)). BL stores the next instruction's address in R14.
94	fn execute_branch(cpu: &mut Cpu, opcode: u32) -> u32 {
95	    let word_offset = ((opcode << 8) as i32) >> 8;
96	    let target = cpu.registers[PROGRAM_COUNTER].wrapping_add((word_offset << 2) as u32);
97	    if bit(opcode, 24) {
98	        cpu.registers[super::LINK_REGISTER] = cpu.current_instruction_address().wrapping_add(4);
99	    }
100	    cpu.branch_to(target);
101	    0
102	}
103	
104	/// BX Rn: jump and switch to THUMB if bit 0 of Rn is set (gbatek: ARM Opcodes: Branch and
105	/// Exchange (BX, BLX)).
106	fn execute_branch_and_exchange(cpu: &mut Cpu, opcode: u32) -> u32 {
107	    let target = read_operand(cpu, register_field(opcode, 0), 0);
108	    cpu.set_thumb_state(target & 1 != 0);
109	    cpu.branch_to(target);
110	    0
111	}
112	
113	// ---- Data processing ----
114	
115	/// Second operand of an ALU op and the shifter carry-out (gbatek: ARM Opcodes: Data Processing
116	/// (ALU), "Second Operand"). Also returns the extra PC offset (4 when shifting by register).
117	fn alu_second_operand(cpu: &Cpu, opcode: u32) -> (u32, bool, u32) {
118	    if bit(opcode, 25) {
119	        let (value, carry) = alu::rotated_immediate(opcode & 0xFF, (opcode >> 8) & 0xF, cpu.carry());
120	        return (value, carry, 0);
121	    }
122	    let shift_type = ShiftType::from_bits((opcode >> 5) & 0b11);
123	    if bit(opcode, 4) {
124	        let operand = read_operand(cpu, register_field(opcode, 0), 4);
125	        let shift_register = cpu.registers[register_field(opcode, 8)];
126	        let (value, carry) = alu::shift_by_register(shift_type, operand, shift_register, cpu.carry());
127	        (value, carry, 4)
128	    } else {
129	        let operand = read_operand(cpu, register_field(opcode, 0), 0);
130	        let (value, carry) = alu::shift_by_immediate(shift_type, operand, (opcode >> 7) & 0x1F, cpu.carry());
131	        (value, carry, 0)
132	    }
133	}
134	
135	/// The 16 ALU opcodes (gbatek: ARM Opcodes: Data Processing (ALU)). Internal cycles: 1I for a
136	/// shift by register.
137	fn execute_data_processing(cpu: &mut Cpu, opcode: u32) -> u32 {
138	    let (second, shifter_carry, extra_pc_offset) = alu_second_operand(cpu, opcode);
139	    let first = read_operand(cpu, register_field(opcode, 16), extra_pc_offset);
140	    let alu_opcode = (opcode >> 21) & 0xF;
141	    let carry = cpu.carry();
142	    let (value, arithmetic) = match alu_opcode {
143	        0x0 | 0x8 => (first & second, None),
144	        0x1 | 0x9 => (first ^ second, None),
145	        0xC => (first | second, None),
146	        0xD => (second, None),
147	        0xE => (first & !second, None),
148	        0xF => (!second, None),
149	        _ => {
150	            let result = match alu_opcode {
151	                0x2 | 0xA => alu::subtract(first, second),
152	                0x3 => alu::subtract(second, first),
153	                0x4 | 0xB => alu::add(first, second),
154	                0x5 => alu::add_with_carry(first, second, carry),
155	                0x6 => alu::subtract_with_carry(first, second, carry),
156	                _ => alu::subtract_with_carry(second, first, carry), // 0x7 RSC
157	            };
158	            (result.value, Some(result))
159	        }
160	    };
161	
162	    let is_test = (0x8..=0xB).contains(&alu_opcode);
163	    let destination_register = register_field(opcode, 12);
164	    let set_flags = bit(opcode, 20);
165	    if set_flags && destination_register == PROGRAM_COUNTER {
166	        // "If S=1, Rd=R15: CPSR = SPSR_<current mode>, PC = result". The test ops (TST..CMN)
167	        // with Rd=R15 restore the CPSR too but leave the PC alone (jsmolka arm.gba checks this).
168	        cpu.restore_cpsr_from_spsr();
169	    } else if set_flags {
170	        match arithmetic {
171	            Some(result) => cpu.set_arithmetic_flags(result),
172	            None => cpu.set_logical_flags(value, shifter_carry),
173	        }
174	    }
175	    if !is_test {
176	        cpu.write_register(destination_register, value);
177	    }
178	    (extra_pc_offset != 0) as u32
179	}
180	
181	// ---- PSR transfer ----
182	
183	/// MRS Rd,Psr and MSR Psr{_field},Op (gbatek: ARM Opcodes: PSR Transfer (MRS, MSR)). 1S, no I.
184	fn execute_psr_transfer(cpu: &mut Cpu, opcode: u32) -> u32 {
185	    let use_spsr = bit(opcode, 22);
186	    if !bit(opcode, 21) {
187	        let value = if use_spsr { cpu.spsr() } else { cpu.cpsr };
188	        cpu.write_register(register_field(opcode, 12), value);
189	        return 0;
190	    }
191	    let value = if bit(opcode, 25) {
192	        alu::rotated_immediate(opcode & 0xFF, (opcode >> 8) & 0xF, cpu.carry()).0
193	    } else {
194	        cpu.registers[register_field(opcode, 0)]
195	    };
196	    if use_spsr {
197	        cpu.write_spsr_fields(value, opcode);
198	    } else {
199	        cpu.write_cpsr_fields(value, opcode);
200	    }
201	    0
202	}
203	
204	// ---- Multiply ----
205	
206	/// The "m" internal cycles of a multiply: 1 to 4 depending on how many top bytes of the
207	/// multiplier are all zero (or all one, when `signed`) (gbatek: ARM Opcodes: Multiply).
208	fn multiplier_cycles(multiplier: u32, signed: bool) -> u32 {
209	    let significant = |mask: u32| {
210	        let top = multiplier & mask;
211	        top != 0 && !(signed && top == mask)
212	    };
213	    if !significant(0xFFFF_FF00) {
214	        1
215	    } else if !significant(0xFFFF_0000) {
216	        2
217	    } else if !significant(0xFF00_0000) {
218	        3
219	    } else {
220	        4
221	    }
222	}
223	
224	/// MUL and MLA (gbatek: ARM Opcodes: Multiply and Multiply-Accumulate). Flags: N and Z; C is
225	/// "destroyed" on ARMv4 and is left unchanged here. Internal cycles: m (MUL) or m+1 (MLA).
226	fn execute_multiply(cpu: &mut Cpu, opcode: u32) -> u32 {
227	    let multiplier = cpu.registers[register_field(opcode, 8)];
228	    let mut result = cpu.registers[register_field(opcode, 0)].wrapping_mul(multiplier);
229	    let accumulate = bit(opcode, 21);
230	    if accumulate {
231	        result = result.wrapping_add(cpu.registers[register_field(opcode, 12)]);
232	    }
233	    cpu.write_register(register_field(opcode, 16), result);
234	    if bit(opcode, 20) {
235	        cpu.set_negative_and_zero(result);
236	    }
237	    multiplier_cycles(multiplier, true) + accumulate as u32
238	}
239	
240	/// UMULL, UMLAL, SMULL, SMLAL: 64-bit product in RdHi:RdLo (gbatek: ARM Opcodes: Multiply Long).
241	/// Flags: N and Z of the 64-bit result. Internal cycles: m+1 (MULL) or m+2 (MLAL).
242	fn execute_multiply_long(cpu: &mut Cpu, opcode: u32) -> u32 {
243	    let signed = bit(opcode, 22);
244	    let accumulate = bit(opcode, 21);
245	    let low_register = register_field(opcode, 12);
246	    let high_register = register_field(opcode, 16);
247	    let multiplicand = cpu.registers[register_field(opcode, 0)];
248	    let multiplier = cpu.registers[register_field(opcode, 8)];
249	    let mut result = if signed {
250	        (multiplicand as i32 as i64).wrapping_mul(multiplier as i32 as i64) as u64
251	    } else {
252	        (multiplicand as u64) * (multiplier as u64)
253	    };
254	    if accumulate {
255	        let accumulator = ((cpu.registers[high_register] as u64) << 32) | cpu.registers[low_register] as u64;
256	        result = result.wrapping_add(accumulator);
257	    }
258	    cpu.write_register(low_register, result as u32);
259	    cpu.write_register(high_register, (result >> 32) as u32);
260	    if bit(opcode, 20) {
261	        cpu.set_negative((result >> 63) != 0);
262	        cpu.set_zero(result == 0);
263	        if multiplier_cycles(multiplier, signed) == 4 {
264	            cpu.set_carry(long_multiply_carry(multiplicand, multiplier, signed));
265	        }
266	    }
267	    multiplier_cycles(multiplier, signed) + 1 + accumulate as u32
268	}
269	
270	/// C after a long multiply that used all four multiplier cycles. gbatek only says "C=destroyed";
271	/// this rule is fitted to the expected flags shown by the mgba-suite multiply-long test screens:
272	/// take the Booth digit of multiplier bits 31-29 (for unsigned, bit 31 counts as +2 instead of
273	/// -2), form digit * Rm with negative digits as the one's complement, and C is bit 32.
274	// ponytail: C stays unchanged for m < 4 and for MUL/MLA, where no test shows the expected value.
275	fn long_multiply_carry(multiplicand: u32, multiplier: u32, signed: bool) -> bool {
276	    let top_bit = |index: u32| ((multiplier >> index) & 1) as i64;
277	    let bit31_weight = if signed { -2 } else { 2 };
278	    let digit = bit31_weight * top_bit(31) + top_bit(30) + top_bit(29);
279	    let magnitude = multiplicand as u64 * digit.unsigned_abs();
280	    let partial_product = if digit < 0 { !magnitude } else { magnitude };
281	    (partial_product >> 32) & 1 != 0
282	}
283	
284	// ---- Memory ----
285	
286	/// Word load with the ARMv4 misaligned rotation: read the aligned word, then rotate right by
287	/// (address AND 3) * 8 (gbatek: ARM CPU Memory Alignments, "Mis-aligned LDR,SWP").
288	fn read_word_rotated(bus: &mut Bus, address: u32) -> u32 {
289	    bus.read32(address & !3).rotate_right((address & 3) * 8)
290	}
291	
292	/// Apply an up/down offset to a base address.
293	fn offset_address(base: u32, offset: u32, up: bool) -> u32 {
294	    if up { base.wrapping_add(offset) } else { base.wrapping_sub(offset) }
295	}
296	
297	/// Shared addressing for LDR/STR and LDRH/STRH: returns (transfer address, written-back base).
298	/// Post-indexing always writes back; pre-indexing only with W (gbatek: ARM Opcodes: Memory).
