        bus.write32(IWRAM, 0x4433_2211);
        cpu.registers[1] = 0xAABB_CCDD;
        cpu.registers[2] = IWRAM;
        execute_arm(&mut cpu, &mut bus, 0xE102_0091); // SWP R0,R1,[R2]
