        cpu.registers[1] = 0x77;
        execute_arm(&mut cpu, &mut bus, 0xE142_0091); // SWPB R0,R1,[R2]
        assert_eq!((cpu.registers[0], bus.read32(IWRAM)), (0xDD, 0xAABB_CC77));
    }

